    "WHATSAPP": re.compile(r"\bwhats\s?app\b", re.I),
    "PLATFORM": re.compile(
        r"\b(sur\s+(?:la\s+|votre\s+l')?(?:plateforme|site|application|app)|"
        r"ici\s+sur\s+(?:votre|la)|depuis\s+(?:votre|l')application)\b",
        re.I,
    ),
    "FACEBOOK": re.compile(r"\b(facebook|f[bbc]\.com|messenger)\b", re.I),
    "TIKTOK": re.compile(r"\btik\s?tok\b", re.I),
    "INSTAGRAM": re.compile(r"\b(instagram|insta|ig)\b", re.I),
    "FRIEND": re.compile(r"\b(amis?|amie|connaissance|voisin|colocataire)\b", re.I),
    "FAMILY": re.compile(
        r"\b(famille|mon\s+p[èe]re|ma\s+m[èe]re|mon\s+fr[èe]re|ma\s+s[œoe]ur|"
        r"cousin[e]?|oncle|tante|parent[s]?)\b",
        re.I,
    ),
    "AGENCY": re.compile(r"\b(agence|agent\s+immobilier|courtier|notaire)\b", re.I),
    "WORD_OF_MOUTH": re.compile(
        r"\b(bouche[-\s]?à[-\s]?oreille|bouche[-\s]?a[-\s]?oreille|on\s+m'a\s+dit|"
        r"on\s+m'a\s+indiqu[ée]|quelqu'un\s+m'a)\b",
        re.I,
    ),
    "OTHER": re.compile(r"\b(autre|ailleurs|google|internet|publicit[ée])\b", re.I),
}

# Someone saying "je veux publier un appartement" has opened a listing, even
# though no price and no room count came with it. Without this the flow would
# sit in SUPPORT for ever, asking a landlord nothing about the flat they are
# trying to rent out.
LISTING_INTENT_PATTERN = re.compile(
    r"\b(je\s+(?:voudrais|souhaite|veux|dois|ai)\s+"
    r"(?:publier|mettre\s+en\s+ligne|vendre|louer|proposer)|"
    r"annonce[er]?|je\s+propose|disponible\s+a\s+louer)\b",
    re.I,
)

SEARCH_INTENT_PATTERN = re.compile(
    r"\b(je\s+(?:cherche|recherche|veux|voudrais)\s+(?:un|une|des)?|"
    r"avez[-\s]?vous\s+(?:un|une)|vous\s+avez\s+(?:un|une|des))\b",
    re.I,
)

LOCATION_HINT_PATTERN = re.compile(
    r"\b(douala|yaound[ée]|[ée]tat|garoua|bafoussam|buea|kribi|limbe|ngaoundéré|"
    r"bastos|bonapriso|akwa|makepe|mvan|bonamoussadi|logbessou|odza|nyalla)\b",
    re.I,
)


@dataclass(frozen=True, slots=True)
class DeterministicMatch:
    intent: str
    confidence: float
    entities: dict[str, object] = field(default_factory=dict)


class DeterministicClassifier:
    """Pure function from message text to a candidate intent."""

    def classify(self, text: str, *, pending: str | None = None) -> DeterministicMatch | None:
        normalized = self._normalize(text)
        if not normalized:
            return None

        availability = self._first_match(AVAILABILITY_PATTERNS, normalized)
        if availability:
            return DeterministicMatch(
                intent=f"AVAILABILITY_{availability}",
                confidence=0.95,
                entities={"availability": availability},
            )

        source = self._first_match(ACQUISITION_SOURCE_PATTERNS, normalized)
        if source:
            return DeterministicMatch(
                intent="COLLECT_ACQUISITION_SOURCE",
                confidence=0.93,
                entities={"acquisition_source": source},
            )

        entities = self._extract_entities(normalized)
        property_type = self._first_match(PROPERTY_TYPE_PATTERNS, normalized)
        if property_type:
            entities["property_type"] = property_type

        wants_to_list = bool(LISTING_INTENT_PATTERN.search(normalized))
        wants_to_search = bool(SEARCH_INTENT_PATTERN.search(normalized))

        # A tenant asking for a flat is never asking to publish one: the two
        # intents open different flows and confusing them would send a tenant
        # through a landlord's form.
        if wants_to_search and not wants_to_list:
            return DeterministicMatch(
                intent="PROPERTY_SEARCH", confidence=0.85, entities=entities
            )
        if property_type and (wants_to_list or "price" in entities or "bedrooms" in entities):
            return DeterministicMatch(
                intent="CREATE_PROPERTY", confidence=0.9, entities=entities
            )
        if property_type:
            return DeterministicMatch(
                intent="COLLECT_PROPERTY_TYPE", confidence=0.9, entities=entities
            )
        if "price" in entities:
            return DeterministicMatch(intent="COLLECT_PRICE", confidence=0.92, entities=entities)
        if {"bedrooms", "bathrooms", "surface_area"} & entities.keys():
            return DeterministicMatch(
                intent="COLLECT_FEATURES", confidence=0.9, entities=entities
            )

        standing = self._standing_reply(normalized, pending)
        if standing is not None:
            return standing
        if "standing" in entities:
            return DeterministicMatch(
                intent="COLLECT_STANDING", confidence=0.9, entities=entities
            )

        if normalized in AFFIRMATIVE:
            return DeterministicMatch(intent="AFFIRMATIVE", confidence=0.98)
        if normalized in NEGATIVE:
            return DeterministicMatch(intent="NEGATIVE", confidence=0.98)

        return None

    def shortcut(
        self, text: str, *, pending: str | None = None
    ) -> DeterministicMatch | None:
        """The unambiguous replies that must never cost a model call.

        Strictly narrower than :meth:`classify`: when a model is available the
        rules are only a fast lane, not the primary reader. An exact "oui"/"non"
        and a message whose only content is a price are the cases where the
        model can add nothing; "je cherche un appartement à Bastos" is not,
        because the intent (search vs listing) is exactly what the model is for.

        ``pending`` is the question the user is answering. It matters for
        "moderne ou non", where a bare "non" is a *value* for the field and not a
        refusal: without it the fast lane would re-ask the question.
        """
        normalized = self._normalize(text)
        if not normalized:
            return None
        standing = self._standing_reply(normalized, pending)
        if standing is not None:
            return standing
        if normalized in AFFIRMATIVE:
            return DeterministicMatch(intent="AFFIRMATIVE", confidence=0.98)
        if normalized in NEGATIVE:
            return DeterministicMatch(intent="NEGATIVE", confidence=0.98)
        entities = self._extract_entities(normalized)
        if "price" in entities and len(normalized.split()) <= 4:
            return DeterministicMatch(
                intent="COLLECT_PRICE",
                confidence=0.92,
                entities={"price": entities["price"]},
            )
        return None

    @staticmethod
    def _standing_reply(
        normalized: str, pending: str | None
    ) -> DeterministicMatch | None:
        """Read "oui"/"non" as MODERN/NON_MODERN when that is the open question."""
        if pending != "ask.standing":
            return None
        if normalized in AFFIRMATIVE:
            return DeterministicMatch(
                intent="COLLECT_STANDING",
                confidence=0.95,
                entities={"standing": "MODERN"},
            )
        if normalized in NEGATIVE:
            return DeterministicMatch(
                intent="COLLECT_STANDING",
                confidence=0.95,
                entities={"standing": "NON_MODERN"},
            )
        return None

    def shorthand_amount(self, text: str) -> int | None:
        """The amount when the message spells it as local shorthand, else None.

        Only the shorthand case is returned: it is exactly where the model's
        prior ("mil" = million) is wrong for this market, so the code owns the
        meaning and overrides the model's number. A plain "250 000" is left to
        the model, which reads it reliably.
        """
        normalized = self._normalize(text)
        for pattern, multiplier in (
            (SHORTHAND_MILLION_PATTERN, 1_000_000),
            (SHORTHAND_THOUSAND_PATTERN, 1_000),
        ):
            match = pattern.search(normalized)
            if match:
                value = _parse_amount(match.group("amount")) * multiplier
                if value >= MIN_PLAUSIBLE_RENT_XAF:
                    return value
        return None

    def to_intent_result(self, match: DeterministicMatch) -> IntentResult:
        return IntentResult(
            intent=match.intent,
            confidence=match.confidence,
            entities=dict(match.entities),
        )

    def _extract_entities(self, normalized: str) -> dict[str, object]:
        entities: dict[str, object] = {}
        raw_amount, multiplier = self._find_amount(normalized)
        if raw_amount is not None:
            value = _parse_amount(raw_amount) * multiplier
            if value >= MIN_PLAUSIBLE_RENT_XAF:
                entities["price"] = value
        bedrooms = BEDROOM_PATTERN.search(normalized)
        if bedrooms:
            entities["bedrooms"] = int(bedrooms.group("count"))
        bathrooms = BATHROOM_PATTERN.search(normalized)
        if bathrooms:
            entities["bathrooms"] = int(bathrooms.group("count"))
        surface = SURFACE_PATTERN.search(normalized)
        if surface:
            entities["surface_area"] = int(surface.group("area"))
        if NON_MODERN_PATTERN.search(normalized):
            entities["standing"] = "NON_MODERN"
        elif MODERN_PATTERN.search(normalized):
            entities["standing"] = "MODERN"
        location = LOCATION_HINT_PATTERN.search(normalized)
        if location:
            entities["location_hint"] = location.group(0).title()
        return entities

    @staticmethod
    def _find_amount(normalized: str) -> tuple[str | None, int]:
        """The first amount in the message, with its locale multiplier.

        Ordered most-specific first: an explicit "fcfa" beats a shorthand, and a
        million ("million"/"mio") beats a thousand ("mil"/"k") so "50 million is
        not read as 50 000.
        """
        for pattern, multiplier in (
            (AMOUNT_PATTERN, 1),
            (SHORTHAND_MILLION_PATTERN, 1_000_000),
            (SHORTHAND_THOUSAND_PATTERN, 1_000),
        ):
            match = pattern.search(normalized)
            if match:
                return match.group("amount"), multiplier
        for pattern in (GROUPED_AMOUNT_PATTERN, PLAIN_AMOUNT_PATTERN):
            match = pattern.search(normalized)
            if match:
                return match.group(1), 1
        return None, 1

    @staticmethod
    def _first_match(patterns: dict[str, re.Pattern[str]], normalized: str) -> str | None:
        for label, pattern in patterns.items():
            if pattern.search(normalized):
                return label
        return None

    @staticmethod
    def _normalize(text: str) -> str:
        folded = (
            text.strip()
            .casefold()
            .replace("\u202f", " ")
            .replace("\u2019", "'")
        )
        return re.sub(r"\s+", " ", folded)


def _parse_amount(raw: str) -> int:
    digits = re.sub(r"[^\d]", "", raw)
    return int(digits) if digits else 0

"""OpenRouter adapter for intent understanding.

Everything vendor-shaped stops here: the domain asks for an ``IntentResult`` and
learns nothing about chat completions or OpenRouter's error shapes. The client
is injectable so tests drive it through ``httpx.MockTransport`` — no test in
this repository reaches the network.
"""

from __future__ import annotations

import functools
import json
import time
from dataclasses import replace
from typing import Any

import httpx

from loka.bounded_contexts.ai.domain.services.ai_provider import (
    IntentResult,
    LlmResponse,
    LlmUsage,
    Prompt,
)
from loka.shared.domain.errors import ExternalServiceUnavailable, RateLimited
from loka.shared.infrastructure.config.settings import AISettings
from loka.shared.infrastructure.logging import get_logger

log = get_logger(__name__)

RETRYABLE_STATUS = frozenset({408, 500, 502, 503, 504})
_MAX_ERROR_BODY = 400


@functools.lru_cache(maxsize=8)
def _pooled_client(base_url: str, timeout: float) -> httpx.AsyncClient:
    """One HTTP client per process, not per message.

    A use case is built for each inbound message, so a client created per model
    would pay a fresh TLS handshake on every WhatsApp message. Keying the client
    on the endpoint keeps connections warm across turns.
    """
    return httpx.AsyncClient(base_url=base_url, timeout=timeout)


class OpenRouterIntentModel:
    """Talks to OpenRouter: understands intents and writes replies."""

    def __init__(
        self,
        settings: AISettings,
        *,
        client: httpx.AsyncClient | None = None,
    ) -> None:
        self._settings = settings
        self._client = client
        self._default = settings.default_model
        self._fallback = settings.fallback_model

    @property
    def model(self) -> str:
        return self._default

    async def understand_intent(self, prompt: Prompt) -> IntentResult:
        api_key = self._settings.api_key.get_secret_value()
        if not api_key:
            # A missing key is a deployment mistake, not a transient failure:
            # raising it here avoids spending a retry budget on a doomed call.
            raise ExternalServiceUnavailable(
                "OpenRouter API key is not configured",
                context={"provider": self._settings.provider},
            )

        answer = await self._complete(prompt, model=self._default, api_key=api_key)
        if answer is None and self._fallback != self._default:
            log.warning("openrouter_primary_model_failed", model=self._default)
            answer = await self._complete(prompt, model=self._fallback, api_key=api_key)
        if answer is None:
            raise ExternalServiceUnavailable(
                "no OpenRouter model could answer the prompt",
                context={"models": [self._default, self._fallback]},
            )

        model, content, usage, latency_ms = answer
        return replace(
            IntentResult.from_structured(_parse_json_object(content)),
            usage=self._usage(model, usage, latency_ms),
        )

    async def generate_response(self, prompt: Prompt) -> LlmResponse:
        """Write the assistant's next message, in plain text.

        No ``response_format``: this call produces prose, not a machine-readable
        object, and forcing JSON here would make the model wrap a sentence in
        braces that the outbound layer would then send verbatim.
        """
        api_key = self._settings.api_key.get_secret_value()
        if not api_key:
            raise ExternalServiceUnavailable(
                "OpenRouter API key is not configured",
                context={"provider": self._settings.provider},
            )

        answer = await self._complete(
            prompt, model=self._default, api_key=api_key, json_mode=False
        )
        if answer is None and self._fallback != self._default:
            log.warning("openrouter_primary_model_failed", model=self._default)
            answer = await self._complete(
                prompt, model=self._fallback, api_key=api_key, json_mode=False
            )
        if answer is None:
            raise ExternalServiceUnavailable(
                "no OpenRouter model could write the reply",
                context={"models": [self._default, self._fallback]},
            )
        model, content, usage, latency_ms = answer
        return LlmResponse(
            content=content.strip(),
            usage=self._usage(model, usage, latency_ms),
        )

    async def _complete(
        self, prompt: Prompt, *, model: str, api_key: str, json_mode: bool = True
    ) -> tuple[str, str, dict[str, Any], int] | None:
        """One attempt. ``None`` means "retryable, try the next model"."""
        client = self._client_for()
        started = time.monotonic()
        try:
            response = await client.post(
                "/chat/completions",
                json=self._body(prompt, model, json_mode=json_mode),
                headers=self._headers(api_key),
            )
        except httpx.HTTPError as exc:
            log.warning("openrouter_transport_error", error=str(exc))
            return None

        latency_ms = int((time.monotonic() - started) * 1000)
        if response.status_code == 429:
            # Raised, not swallowed: a rate limit means the caller must slow
            # down. Swallowing it would turn "we are being throttled" into a
            # confident "UNKNOWN" and then a wrong question to the landlord.
            raise RateLimited(
                "OpenRouter rate limit reached", context={"model": model}
            )
        if response.status_code in RETRYABLE_STATUS:
            log.warning(
                "openrouter_retryable_status",
                extra={"status": response.status_code, "model": model},
            )
            return None
        if response.is_error:
            raise ExternalServiceUnavailable(
                "OpenRouter rejected the request",
                context={
                    "status": response.status_code,
                    "model": model,
                    "body": response.text[:_MAX_ERROR_BODY],
                },
            )

        content, usage = self._read(response, model=model)
        return model, content, usage, latency_ms

    def _client_for(self) -> httpx.AsyncClient:
        if self._client is not None:
            return self._client
        # Never closed here: it is shared across the process and lives as long as
        # the worker does.
        return _pooled_client(
            self._settings.base_url, self._settings.request_timeout_seconds
        )

    @staticmethod
    def _headers(api_key: str) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            # OpenRouter attributes usage by these headers; without them the
            # vendor bill cannot be reconciled against our own ledger.
            "HTTP-Referer": "https://loka.cm",
            "X-Title": "Loka",
        }

    @staticmethod
    def _read(response: httpx.Response, *, model: str) -> tuple[str, dict[str, Any]]:
        try:
            payload = response.json()
            content = payload["choices"][0]["message"]["content"]
        except (ValueError, KeyError, IndexError, TypeError) as exc:
            raise ExternalServiceUnavailable(
                "OpenRouter returned an unreadable payload",
                context={"model": model, "error": str(exc)},
            ) from exc
        if not isinstance(content, str) or not content.strip():
            raise ExternalServiceUnavailable(
                "OpenRouter returned an empty completion", context={"model": model}
            )
        usage = payload.get("usage")
        return content, usage if isinstance(usage, dict) else {}

    def _usage(self, model: str, usage: dict[str, Any], latency_ms: int) -> LlmUsage:
        input_tokens = int(usage.get("prompt_tokens") or 0)
        output_tokens = int(usage.get("completion_tokens") or 0)
        pricing = self._settings.pricing_for(model)
        if pricing is None:
            # In production composition refuses to enable the pipeline without
            # pricing, so this is unreachable outside tests. It records zero
            # rather than a guess: a fabricated price would silently corrupt
            # every budget that reads this back.
            log.error("openrouter_missing_pricing", model=model)
            cost = 0.0
        else:
            cost = (input_tokens * pricing.input + output_tokens * pricing.output) / 1_000_000
        return LlmUsage(
            input_tokens=input_tokens,
            output_tokens=output_tokens,
            latency_ms=latency_ms,
            estimated_cost_usd=cost,
            model=model,
        )

    def _body(self, prompt: Prompt, model: str, *, json_mode: bool = True) -> dict[str, Any]:
        body: dict[str, Any] = {
            "model": model,
            "temperature": prompt.temperature,
            "max_tokens": prompt.max_output_tokens,
            "messages": [
                {"role": "system", "content": prompt.system},
                {"role": "user", "content": prompt.user},
            ],
            **prompt.extra,
        }
        if json_mode:
            # Plain JSON mode rather than a vendor schema: the shape is already
            # enforced twice downstream (the prompt, then the value objects), so
            # a stricter contract here would only add a failure mode.
            body["response_format"] = {"type": "json_object"}
        return body


def _parse_json_object(content: str) -> dict[str, Any]:
    text = content.strip()
    if text.startswith("```"):
        # Some models fence their JSON even when told not to.
        text = text.strip("`")
        _, _, text = text.partition("\n")
        text = text.rsplit("```", 1)[0].strip()
    try:
        payload = json.loads(text)
    except ValueError as exc:
        raise ExternalServiceUnavailable(
            "model completion was not valid JSON", context={"error": str(exc)}
        ) from exc
    if not isinstance(payload, dict):
        raise ExternalServiceUnavailable("model completion was not a JSON object")
    return payload

