        self, extractor: FactExtractor
    ) -> None:
        cases = [
            ({"property_type": "APARTMENT"}, FlowStep.COLLECT_STANDING),
            (
                {"property_type": "APARTMENT", "standing": "MODERN"},
                FlowStep.COLLECT_LOCATION,
            ),
