"""Deterministic validation of extracted facts.

Whatever produced the candidates — regex rules or a language model — the
values must survive the *domain's* value objects before they are allowed
anywhere near a session. A model is a good guesser and a bad authority:
"150 000 000 000" or "-2 chambres" must never reach a listing, and the cheapest
place to refuse them is here, in code, with one rule for every source.

Refused fields are dropped, never repaired. The conversation asks again.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from loka.bounded_contexts.messaging.domain.entities.conversation_session import (
    FlowName,
    FlowStep,
)
from loka.bounded_contexts.property.domain.value_objects.enums import (
    BedroomCount,
    PropertyStanding,
    PropertyType,
    SurfaceArea,
)
from loka.bounded_contexts.property.domain.value_objects.location import Location
from loka.bounded_contexts.property.domain.value_objects.money import Money
from loka.shared.domain.errors import DomainError, ValidationFailed

# A rent below this is a misparse, not a negotiation: "150" for "150 000" is the
# most common extraction error, and accepting it would create an unbelievable
# listing that then pollutes search results.
MIN_PLAUSIBLE_RENT_XAF = 10_000
MAX_PLAUSIBLE_RENT_XAF = 500_000_000

# The order is the conversation order: it decides what is asked next. It matches
# how people describe a home here: the type first ("appart", "studio", "chambre"),
# then modern or not, then where it is, then the rent. The bathroom count and the
# surface are deliberately *not* asked: they are rarely known and rarely used,
# and the answer that sells the place is the photos.
PROPERTY_REQUIREMENTS: tuple[tuple[str, FlowStep], ...] = (
    ("property_type", FlowStep.COLLECT_PROPERTY_TYPE),
    ("standing", FlowStep.COLLECT_STANDING),
    ("location", FlowStep.COLLECT_LOCATION),
    ("rent", FlowStep.COLLECT_PRICE),
)

# Intents that concern a listing or a search. Everything else — "merci", "c'est
# loué", "je vais réfléchir" — records its turn but must never move a listing
# form forward.
LISTING_INTENTS = frozenset(
    {
        "CREATE_PROPERTY",
        "PROPERTY_SEARCH",
        "COLLECT_PROPERTY_TYPE",
        "COLLECT_LOCATION",
        "COLLECT_PRICE",
        "COLLECT_FEATURES",
        "COLLECT_STANDING",
        "COLLECT_CHARGES",
        "COLLECT_MINIMUM_DURATION",
        "COLLECT_AVAILABILITY",
        "COLLECT_CONDITIONS",
        "COLLECT_SEARCH_CRITERIA",
    }
)

# The intents that *open* a flow, mapped to the flow they open. Recorded rather
# than inferred, because starting the wrong flow strands the user in a form for
# something they never asked for.
FLOW_BY_OPENING_INTENT: dict[str, FlowName] = {
    "CREATE_PROPERTY": FlowName.PROPERTY_CREATION,
    "PROPERTY_SEARCH": FlowName.PROPERTY_SEARCH,
}

LISTING_FLOWS = frozenset({FlowName.PROPERTY_CREATION, FlowName.PROPERTY_SEARCH})

# Intents the pipeline may act on. Anything else means the model invented a
# state the platform does not have, so the message is treated as untrusted.
#
# `test_fact_extraction.py` asserts that every intent `DeterministicClassifier`
# can emit appears here: this set is the trust boundary, so it has to be closed
# by a test rather than by memory.
SUPPORTED_INTENTS = frozenset(
    {
        # Deterministic classifier.
        "CREATE_PROPERTY",
        "COLLECT_PROPERTY_TYPE",
        "COLLECT_PRICE",
        "COLLECT_FEATURES",
        "COLLECT_STANDING",
        "COLLECT_ACQUISITION_SOURCE",
        "AVAILABILITY_STILL_AVAILABLE",
        "AVAILABILITY_RENTED",
        "AVAILABILITY_TEMPORARILY_UNAVAILABLE",
        "AFFIRMATIVE",
        "NEGATIVE",
        # Flow-level intents a model may propose.
        "COLLECT_LOCATION",
        "COLLECT_CHARGES",
        "COLLECT_MINIMUM_DURATION",
        "COLLECT_AVAILABILITY",
        "COLLECT_CONDITIONS",
        "COLLECT_SEARCH_CRITERIA",
        "PROPERTY_SEARCH",
        "AVAILABILITY_CHECK",
        "APPLICATION_FLOW",
        "TENANT_ONBOARDING",
        "VISIT_SCHEDULING",
        "REPORT_FLOW",
        "SUPPORT",
        "UNKNOWN",
    }
)

# Confidence below this never moves the conversation. The turn is still
# recorded, so "the model was unsure" is measurable instead of being silently
# converted into a wrong listing.
MIN_ACCEPTED_CONFIDENCE = 0.75

# A stable key, never a sentence: copy and translations belong to the outbound
# layer. This stage decides *what* is missing, not how to phrase it.
QUESTION_BY_STEP: dict[FlowStep, str] = {
    FlowStep.COLLECT_PROPERTY_TYPE: "ask.property_type",
    FlowStep.COLLECT_STANDING: "ask.standing",
    FlowStep.COLLECT_LOCATION: "ask.location",
    FlowStep.COLLECT_PRICE: "ask.rent",
    FlowStep.COLLECT_FEATURES: "ask.features",
    FlowStep.COLLECT_CHARGES: "ask.charges",
    FlowStep.COLLECT_MINIMUM_DURATION: "ask.minimum_duration",
    FlowStep.COLLECT_AVAILABILITY: "ask.availability",
    FlowStep.COLLECT_CONDITIONS: "ask.conditions",
    FlowStep.CONFIRM_PROPERTY: "ask.confirm_property",
    FlowStep.PUBLISHED: "confirm.published",
}


@dataclass(frozen=True, slots=True)
class ExtractedFacts:
    """Facts the domain accepted, and why the others were refused."""

    facts: dict[str, Any] = field(default_factory=dict)
    rejected: dict[str, str] = field(default_factory=dict)

    def has(self, name: str) -> bool:
        return name in self.facts

    def get(self, name: str, default: Any = None) -> Any:
        return self.facts.get(name, default)

    def as_context(self) -> dict[str, Any]:
        """Exactly what may be merged into a session's context.

        Built from ``facts`` alone, so a key invented upstream cannot reach the
        durable state even if the validator is later extended carelessly.
        """
        return dict(self.facts)


class FactExtractor:
    """Validates candidate entities through the domain value objects."""

    def validate(self, entities: dict[str, Any]) -> ExtractedFacts:
        facts: dict[str, Any] = {}
        rejected: dict[str, str] = {}

        # A model is told to answer null when unsure, so a null or empty value
        # is "the field was not extracted", not "extracted as nothing".
        present = {
            name: value
            for name, value in entities.items()
            if value is not None and str(value).strip() != ""
        }

        def keep(name: str, build: Any) -> None:
            try:
                facts[name] = build()
            except DomainError as exc:
                rejected[name] = exc.message
            except (TypeError, ValueError) as exc:
                # Value objects raise DomainError when they refuse a value, but
                # a StrEnum lookup ("property_type": "NONE") raises ValueError:
                # both are "this candidate is not a valid domain value" and the
                # field is dropped, never repaired.
                rejected[name] = str(exc)

        if "property_type" in present:
            keep(
                "property_type",
                lambda: PropertyType(str(present["property_type"]).upper()).value,
            )
        if "standing" in present or "modern" in present:
            keep("standing", lambda: _build_standing(entities))
        if "city" in present:
            keep("location", lambda: self._build_location(entities))
        elif "location_hint" in present:
            # A bare neighbourhood ("Bastos") stays a hint. Promoting it to a
            # city would put Douala's Bonapriso into the city column.
            keep("location_hint", lambda: _clean_hint(present["location_hint"]))
        if "price" in present:
            keep("rent", lambda: self._build_rent(present["price"]))
        if "bedrooms" in present or "bathrooms" in present:
            keep("rooms", lambda: self._build_rooms(entities))
        if "surface_area" in present:
            keep(
                "surface",
                lambda: SurfaceArea(square_metres=_as_int(present["surface_area"])).square_metres,
            )
        if "charges" in present:
            keep(
                "charges",
                lambda: Money(amount=_as_int(present["charges"]))
                .require_positive(reason="charges must be positive")
                .amount,
            )
        if "minimum_duration_months" in present:
            keep("minimum_duration_months", lambda: _as_int(present["minimum_duration_months"]))
        if "availability" in present:
            keep("availability", lambda: str(present["availability"]).upper())

        return ExtractedFacts(facts=facts, rejected=rejected)

    def next_step(
        self,
        intent: str,
        facts: ExtractedFacts,
        *,
        flow: FlowName,
        known: dict[str, Any] | None = None,
    ) -> FlowStep | None:
        """Where the conversation goes next, decided here and nowhere else.

        A model may propose facts; the order in which they are asked is a
        business rule and is not negotiable by a suggestion engine. ``flow`` is
        required rather than optional on purpose: an amount dropped into a
        support conversation must be recorded, not treated as the first answer
        to a listing form the user never started.

        ``known`` is what the session already holds. Without it the next step is
        computed from the current message alone, so a landlord who gives their
        city after already naming the property type gets asked for the type
        again — the form restarts on every turn instead of advancing.
        """
        if intent not in LISTING_INTENTS:
            return None
        if intent in FLOW_BY_OPENING_INTENT:
            return self._first_missing(facts, known)
        if flow not in LISTING_FLOWS:
            return None
        return self._first_missing(facts, known)

    @staticmethod
    def _first_missing(facts: ExtractedFacts, known: dict[str, Any] | None = None) -> FlowStep:
        already_known = known or {}
        for name, step in PROPERTY_REQUIREMENTS:
            if not facts.has(name) and name not in already_known:
                return step
        return FlowStep.CONFIRM_PROPERTY

    @staticmethod
    def _build_rent(raw: Any) -> int:
        amount = Money(amount=_as_int(raw)).require_positive(reason="rent must be positive")
        if amount.amount > MAX_PLAUSIBLE_RENT_XAF:
            raise ValidationFailed(
                "rent is above the plausible range for this market",
                context={"amount": amount.amount, "ceiling": MAX_PLAUSIBLE_RENT_XAF},
            )
        return amount.amount

    @staticmethod
    def _build_rooms(entities: dict[str, Any]) -> dict[str, int]:
        rooms = BedroomCount(
            count=_as_int(entities.get("bedrooms", 0)),
            bathrooms=_as_int(entities.get("bathrooms", 1)),
        )
        return {"bedrooms": rooms.count, "bathrooms": rooms.bathrooms}

    @staticmethod
    def _build_location(entities: dict[str, Any]) -> dict[str, str]:
        city = str(entities.get("city") or "").strip()
        if not city:
            raise ValidationFailed("no city was extracted", context={"entities": sorted(entities)})
        neighbourhood = entities.get("neighbourhood")
        location = Location(
            city=city,
            neighbourhood=str(neighbourhood) if isinstance(neighbourhood, str) else None,
        )
        return {"city": location.city, "neighbourhood": location.neighbourhood or ""}


def is_supported_intent(intent: str) -> bool:
    return intent in SUPPORTED_INTENTS


def question_key_for(step: FlowStep | None) -> str | None:
    return None if step is None else QUESTION_BY_STEP.get(step)


def _as_int(raw: Any) -> int:
    """Coerce a candidate number, or refuse it as a validation failure.

    A model may answer ``{"price": "beaucoup"}``. ``int()`` raises ``ValueError``
    there, which is not a ``DomainError``: without this the exception escapes
    the extractor and crashes the consumer instead of dropping the field and
    asking the question again.
    """
    if isinstance(raw, bool) or raw is None:
        raise ValidationFailed("expected a number", context={"value": repr(raw)})
    try:
        return int(raw)
    except (TypeError, ValueError) as exc:
        raise ValidationFailed(
            "expected a number", context={"value": repr(raw)}
        ) from exc


def _clean_hint(raw: Any) -> str:
    hint = str(raw).strip()
    if len(hint) < 2:
        raise ValidationFailed("location hint is too vague", context={"value": raw})
    return hint


_STANDING_ALIASES: dict[str, PropertyStanding] = {
    "MODERN": PropertyStanding.MODERN,
    "MODERNE": PropertyStanding.MODERN,
    "NON_MODERN": PropertyStanding.NON_MODERN,
    "NON_MODERNE": PropertyStanding.NON_MODERN,
    "ANCIEN": PropertyStanding.NON_MODERN,
    "ANCIENNE": PropertyStanding.NON_MODERN,
}


def _build_standing(entities: dict[str, Any]) -> str:
    """Read "moderne ou non" from either spelling the model may produce.

    A model handed a French message often answers ``"modern": true`` rather than
    the ``standing`` enum; both are accepted and normalised to one value, so the
    rest of the form never has to know which wording arrived.
    """
    raw = entities.get("standing")
    if raw is None and "modern" in entities:
        modern = entities["modern"]
        if isinstance(modern, bool):
            return (
                PropertyStanding.MODERN.value if modern else PropertyStanding.NON_MODERN.value
            )
        raw = modern
    text = str(raw).strip().upper().replace(" ", "_").replace("-", "_")
    if text in _STANDING_ALIASES:
        return _STANDING_ALIASES[text].value
    return PropertyStanding(text).value

"""Property enums and supporting value objects."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from enum import StrEnum

from loka.shared.domain.value_object import ValueObject


class PropertyType(StrEnum):
    APARTMENT = "APARTMENT"
    HOUSE = "HOUSE"
    STUDIO = "STUDIO"
    ROOM = "ROOM"
    DUPLEX = "DUPLEX"
    LOFT = "LOFT"
    COMMERCIAL = "COMMERCIAL"
    LAND = "LAND"


class PropertyStanding(StrEnum):
    """Whether the place is modern or not.

    In this market the second question after the type is not the bathroom count
    or the surface, it is "moderne ou non": it is how tenants actually filter.
    """

    MODERN = "MODERN"
    NON_MODERN = "NON_MODERN"


class PropertyStatus(StrEnum):
    DRAFT = "DRAFT"
    AVAILABLE = "AVAILABLE"
    RESERVED = "RESERVED"
    RENTED = "RENTED"
    UNAVAILABLE = "UNAVAILABLE"
    SUSPENDED = "SUSPENDED"
    ARCHIVED = "ARCHIVED"


class DataQualityIssue(StrEnum):
    MISSING_CHARGES = "MISSING_CHARGES"
    MISSING_PHOTOS = "MISSING_PHOTOS"
    MISSING_MINIMUM_DURATION = "MISSING_MINIMUM_DURATION"
    MISSING_AVAILABILITY_DATE = "MISSING_AVAILABILITY_DATE"
    VAGUE_LOCATION = "VAGUE_LOCATION"
    SUSPICIOUS_PRICE = "SUSPICIOUS_PRICE"
    MISSING_DEPOSIT = "MISSING_DEPOSIT"
    AMBIGUOUS_CONDITIONS = "AMBIGUOUS_CONDITIONS"

class ChargingPolicy(StrEnum):
    INCLUDED = "INCLUDED"
    EXTRA = "EXTRA"
    UNKNOWN = "UNKNOWN"

class PropertyDraftData(StrEnum):
    TYPE = "TYPE"
    LOCATION = "LOCATION"
    PRICE = "PRICE"
    CHARGES = "CHARGES"
    FEATURES = "FEATURES"
    MEDIA = "MEDIA"
    DEPOSIT = "DEPOSIT"
    MINIMUM_DURATION = "MINIMUM_DURATION"
    CONDITIONS = "CONDITIONS"
    AVAILABILITY = "AVAILABILITY"
    SUMMARY_CONFIRMATION = "SUMMARY_CONFIRMATION"


class AvailabilityAnswer(StrEnum):
    """Answers a landlord may give when availability is re-confirmed."""

    STILL_AVAILABLE = "STILL_AVAILABLE"
    RENTED = "RENTED"
    TEMPORARILY_UNAVAILABLE = "TEMPORARILY_UNAVAILABLE"


@dataclass(frozen=True, slots=True)
class Duration(ValueObject):
    """Minimum lease length; always expressed in whole months."""


    months: int

    def __post_init__(self) -> None:
        if not 1 <= self.months <= 120:
            self._reject("minimum duration must be between 1 and 120 months", months=self.months)

    @property
    def label(self) -> str:
        if self.months == 12:
            return "1 an"
        return f"{self.months} mois"

    def months_from(self, start: date) -> date:
        if self.months == 12:
            return start.replace(year=start.year + 1)
        total = start.month - 1 + self.months
        year = start.year + total // 12
        month = total % 12 + 1
        day = min(start.day, _days_in_month(year, month))
        return date(year, month, day)


@dataclass(frozen=True, slots=True)
class AvailabilityWindow(ValueObject):
    """When the property becomes occupiable. Never inferred from a status flag."""


    available_from: date

    def is_immediate(self) -> bool:
        return self.available_from <= date.today()

    def label(self) -> str:
        if self.is_immediate():
            return "disponible immédiatement"
        return f"disponible à partir du {self.available_from.strftime('%d/%m/%Y')}"


@dataclass(frozen=True, slots=True)
class BedroomCount(ValueObject):

    count: int
    bathrooms: int = 1

    def __post_init__(self) -> None:
        if not 0 <= self.count <= 50:
            self._reject("bedroom count out of range", count=self.count)
        if not 0 <= self.bathrooms <= 50:
            self._reject("bathroom count out of range", bathrooms=self.bathrooms)


@dataclass(frozen=True, slots=True)
class SurfaceArea(ValueObject):

    square_metres: int

    def __post_init__(self) -> None:
        if not 5 <= self.square_metres <= 10_000:
            self._reject("surface area out of realistic bounds", square_metres=self.square_metres)


def _days_in_month(year: int, month: int) -> int:
    import calendar

    return calendar.monthrange(year, month)[1]

"""Deterministic intent classification.

Two entry points, with different jobs:

* :meth:`DeterministicClassifier.shortcut` is the cheap path used when a model
  is available. It only fires on messages that carry no ambiguity at all — an
  exact "oui"/"non" or a bare amount — where spending a model call would be
  pure waste. Everything else goes to the model first.
* :meth:`DeterministicClassifier.classify` is the fuller rule set used when no
  model is configured, so the platform still answers with regexes alone.

Anything neither can resolve returns ``None``, which is the signal to fall back
rather than guess.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

from loka.bounded_contexts.ai.domain.services.ai_provider import IntentResult
from loka.bounded_contexts.ai.domain.services.fact_extraction import (
    MIN_PLAUSIBLE_RENT_XAF,
)

AFFIRMATIVE = frozenset(
    {
        "oui",
        "ouais",
        "yes",
        "y",
        "ok",
        "okay",
        "daccord",
        "d accord",
        "ca me va",
        "exact",
        "parfait",
        "super",
        "merci",
        "ca marche",
        "bien",
        "valide",
        "confirme",
        "confirmation",
    }
)
NEGATIVE = frozenset(
    {
        "non",
        "no",
        "n",
        "jamais",
        "refuse",
        "refusee",
        "annule",
        "annulee",
        "je ne veux pas",
        "autre chose",
        "stop",
        "laisse tomber",
        "finalement non",
    }
)

AMOUNT_PATTERN = re.compile(
    r"(?P<amount>\d[\d\s.\u202f]{2,12}?)\s*(?:fcfa|xaf|cfa|frs|f\b)", re.IGNORECASE
)
GROUPED_AMOUNT_PATTERN = re.compile(r"(?<![\d.])(\d{1,3}(?:[ .\u202f]\d{3})+)(?![\d.])")
PLAIN_AMOUNT_PATTERN = re.compile(r"(?<![\d.])(\d{5,9})(?![\d.])")
# Local shorthand: in Cameroonian French "50 mil" is 50 000, but "mil" reads as
# "million" in most of a model's training data. The model is a bad place to
# settle a locale convention, so the meaning is owned here, in a rule.
SHORTHAND_MILLION_PATTERN = re.compile(
    r"(?<![\d.])(?P<amount>\d[\d\s.\u202f]{0,12}?)\s*(?:millions?|miyons?|mio)\b",
    re.IGNORECASE,
)
SHORTHAND_THOUSAND_PATTERN = re.compile(
    r"(?<![\d.])(?P<amount>\d[\d\s.\u202f]{0,12}?)\s*(?:milles?|mil|k)\b",
    re.IGNORECASE,
)
BEDROOM_PATTERN = re.compile(
    r"(?P<count>\d{1,2})\s*(?:chambres?|pieces?|pi[eè]ces?|bed\s?rooms?)", re.IGNORECASE
)
BATHROOM_PATTERN = re.compile(
    r"(?P<count>\d{1,2})\s*(?:salle[s]?\s+de\s+bain|salles?\s+d'eau|sdb|douches?)",
    re.IGNORECASE,
)
SURFACE_PATTERN = re.compile(r"(?P<area>\d{2,4})\s*m(?:2|²|sup)?(?![a-z])", re.IGNORECASE)
MODERN_PATTERN = re.compile(
    r"\b(moderne|modernes|neuf|neuve|recent|recente|standing)\b", re.IGNORECASE
)
NON_MODERN_PATTERN = re.compile(
    r"\b(non[\s-]?moderne|ancien|ancienne|vieux|vieille|vetuste|a refaire)\b", re.IGNORECASE
)

PROPERTY_TYPE_PATTERNS: dict[str, re.Pattern[str]] = {
    "APARTMENT": re.compile(r"\b(appartement|appart|apt|immeuble|appartement[s]?)\b", re.I),
    "STUDIO": re.compile(r"\b(studios?|sbg)\b", re.I),
    "HOUSE": re.compile(r"\b(maisons?|villas?|demeures?|townhouses?)\b", re.I),
    "DUPLEX": re.compile(r"\b(duplexs?|duplexe?s?)\b", re.I),
    "LOFT": re.compile(r"\b(lofts?)\b", re.I),
    "ROOM": re.compile(
        r"\b(chambres?\s+(?:meubl[ée]e?s?|a\s+louer|à\s+louer|d'etudiant|"
        r"d'[ée]tudiant|d'[ée]tage|partag[ée]e?s?)|chambres?\s+hote?s?)\b",
        re.I,
    ),
    "COMMERCIAL": re.compile(
        r"\b(boutiques?|commerces?|magasins?|bureaux?|locaux?\s+commerciaux?s?|"
        r"salons?\s+de\s+coiffure)\b",
        re.I,
    ),
    "LAND": re.compile(r"\b(terrains?|parcelles?|lots?|terrains?\s+a\s+b[aâ]tir)\b", re.I),
}

AVAILABILITY_PATTERNS: dict[str, re.Pattern[str]] = {
    "STILL_AVAILABLE": re.compile(
        r"\b(toujours\s+(?:disponible|libre|ok|dispo|valide)|c'est\s+toujours|"
        r"toujours\s+[aà]\s+louer|elle\s+est\s+toujours)\b",
        re.I,
    ),
    "RENTED": re.compile(
        r"\b(d[ée]j[àa]\s+lou[ée]|c'?est\s+lou[ée]|est\s+d[ée]j[àa]\s+lou[ée]|"
        r"[àa]\s+[ée]t[ée]\s+lou[ée]|j'?ai\s+lou[ée]|on\s+a\s+lou[ée]|"
        r"j'ai\s+trouv[ée]\s+(?:un\s+)?locataire|elle\s+est\s+lou[ée]|"
        r"c'est\s+d[ée]j[àa]\s+pris|parti\s+avec)\b",
        re.I,
    ),
    "TEMPORARILY_UNAVAILABLE": re.compile(
        r"\b(indisponibles?|pas\s+(?:dispo|disponible)|temporairement|"
        r"en\s+travaux?|parti[es]?\s+en\s+vacances?|sous\s+location\s+temporaire)\b",
        re.I,
    ),
}

ACQUISITION_SOURCE_PATTERNS: dict[str, re.Pattern[str]] = {
    "WHATSAPP": re.compile(r"\bwhats\s?app\b", re.I),
    "PLATFORM": re.compile(
        r"\b(sur\s+(?:la\s+|votre\s+l')?(?:plateforme|site|application|app)|"
        r"ici\s+sur\s+(?:votre|la)|depuis\s+(?:votre|l')application)\b",
        re.I,
    ),
    "FACEBOOK": re.compile(r"\b(facebook|f[bbc]\.com|messenger)\b", re.I),
    "TIKTOK": re.compile(r"\btik\s?tok\b", re.I),
    "INSTAGRAM": re.compile(r"\b(instagram|insta|ig)\b", re.I),
    "FRIEND": re.compile(r"\b(amis?|amie|connaissance|voisin|colocataire)\b", re.I),
    "FAMILY": re.compile(
        r"\b(famille|mon\s+p[èe]re|ma\s+m[èe]re|mon\s+fr[èe]re|ma\s+s[œoe]ur|"
        r"cousin[e]?|oncle|tante|parent[s]?)\b",
        re.I,
    ),
    "AGENCY": re.compile(r"\b(agence|agent\s+immobilier|courtier|notaire)\b", re.I),
    "WORD_OF_MOUTH": re.compile(
        r"\b(bouche[-\s]?à[-\s]?oreille|bouche[-\s]?a[-\s]?oreille|on\s+m'a\s+dit|"
        r"on\s+m'a\s+indiqu[ée]|quelqu'un\s+m'a)\b",
        re.I,
    ),
    "OTHER": re.compile(r"\b(autre|ailleurs|google|internet|publicit[ée])\b", re.I),
}

# Someone saying "je veux publier un appartement" has opened a listing, even
# though no price and no room count came with it. Without this the flow would
# sit in SUPPORT for ever, asking a landlord nothing about the flat they are
# trying to rent out.
LISTING_INTENT_PATTERN = re.compile(
    r"\b(je\s+(?:voudrais|souhaite|veux|dois|ai)\s+"
    r"(?:publier|mettre\s+en\s+ligne|vendre|louer|proposer)|"
    r"annonce[er]?|je\s+propose|disponible\s+a\s+louer)\b",
    re.I,
)

SEARCH_INTENT_PATTERN = re.compile(
    r"\b(je\s+(?:cherche|recherche|veux|voudrais)\s+(?:un|une|des)?|"
    r"avez[-\s]?vous\s+(?:un|une)|vous\s+avez\s+(?:un|une|des))\b",
    re.I,
)

LOCATION_HINT_PATTERN = re.compile(
    r"\b(douala|yaound[ée]|[ée]tat|garoua|bafoussam|buea|kribi|limbe|ngaoundéré|"
    r"bastos|bonapriso|akwa|makepe|mvan|bonamoussadi|logbessou|odza|nyalla)\b",
    re.I,
)


@dataclass(frozen=True, slots=True)
class DeterministicMatch:
    intent: str
    confidence: float
    entities: dict[str, object] = field(default_factory=dict)


class DeterministicClassifier:
    """Pure function from message text to a candidate intent."""

    def classify(self, text: str, *, pending: str | None = None) -> DeterministicMatch | None:
        normalized = self._normalize(text)
        if not normalized:
            return None

        availability = self._first_match(AVAILABILITY_PATTERNS, normalized)
        if availability:
            return DeterministicMatch(
                intent=f"AVAILABILITY_{availability}",
                confidence=0.95,
                entities={"availability": availability},
            )

        source = self._first_match(ACQUISITION_SOURCE_PATTERNS, normalized)
        if source:
            return DeterministicMatch(
                intent="COLLECT_ACQUISITION_SOURCE",
                confidence=0.93,
                entities={"acquisition_source": source},
            )

        entities = self._extract_entities(normalized)
        property_type = self._first_match(PROPERTY_TYPE_PATTERNS, normalized)
        if property_type:
            entities["property_type"] = property_type

        wants_to_list = bool(LISTING_INTENT_PATTERN.search(normalized))
        wants_to_search = bool(SEARCH_INTENT_PATTERN.search(normalized))

        # A tenant asking for a flat is never asking to publish one: the two
        # intents open different flows and confusing them would send a tenant
        # through a landlord's form.
        if wants_to_search and not wants_to_list:
            return DeterministicMatch(
                intent="PROPERTY_SEARCH", confidence=0.85, entities=entities
            )
        if property_type and (wants_to_list or "price" in entities or "bedrooms" in entities):
            return DeterministicMatch(
                intent="CREATE_PROPERTY", confidence=0.9, entities=entities
            )
        if property_type:
            return DeterministicMatch(
                intent="COLLECT_PROPERTY_TYPE", confidence=0.9, entities=entities
            )
        if "price" in entities:
            return DeterministicMatch(intent="COLLECT_PRICE", confidence=0.92, entities=entities)
        if {"bedrooms", "bathrooms", "surface_area"} & entities.keys():
            return DeterministicMatch(
                intent="COLLECT_FEATURES", confidence=0.9, entities=entities
            )

        standing = self._standing_reply(normalized, pending)
        if standing is not None:
            return standing
        if "standing" in entities:
            return DeterministicMatch(
                intent="COLLECT_STANDING", confidence=0.9, entities=entities
            )

        if normalized in AFFIRMATIVE:
            return DeterministicMatch(intent="AFFIRMATIVE", confidence=0.98)
        if normalized in NEGATIVE:
            return DeterministicMatch(intent="NEGATIVE", confidence=0.98)

        return None

    def shortcut(
        self, text: str, *, pending: str | None = None
    ) -> DeterministicMatch | None:
        """The unambiguous replies that must never cost a model call.

        Strictly narrower than :meth:`classify`: when a model is available the
        rules are only a fast lane, not the primary reader. An exact "oui"/"non"
        and a message whose only content is a price are the cases where the
        model can add nothing; "je cherche un appartement à Bastos" is not,
        because the intent (search vs listing) is exactly what the model is for.

        ``pending`` is the question the user is answering. It matters for
        "moderne ou non", where a bare "non" is a *value* for the field and not a
        refusal: without it the fast lane would re-ask the question.
        """
        normalized = self._normalize(text)
        if not normalized:
            return None
        standing = self._standing_reply(normalized, pending)
        if standing is not None:
            return standing
        if normalized in AFFIRMATIVE:
            return DeterministicMatch(intent="AFFIRMATIVE", confidence=0.98)
        if normalized in NEGATIVE:
            return DeterministicMatch(intent="NEGATIVE", confidence=0.98)
        entities = self._extract_entities(normalized)
        if "price" in entities and len(normalized.split()) <= 4:
            return DeterministicMatch(
                intent="COLLECT_PRICE",
                confidence=0.92,
                entities={"price": entities["price"]},
            )
        return None

    @staticmethod
    def _standing_reply(
        normalized: str, pending: str | None
    ) -> DeterministicMatch | None:
        """Read "oui"/"non" as MODERN/NON_MODERN when that is the open question."""
        if pending != "ask.standing":
            return None
        if normalized in AFFIRMATIVE:
            return DeterministicMatch(
                intent="COLLECT_STANDING",
                confidence=0.95,
                entities={"standing": "MODERN"},
            )
        if normalized in NEGATIVE:
            return DeterministicMatch(
                intent="COLLECT_STANDING",
                confidence=0.95,
                entities={"standing": "NON_MODERN"},
            )
        return None

    def shorthand_amount(self, text: str) -> int | None:
        """The amount when the message spells it as local shorthand, else None.

        Only the shorthand case is returned: it is exactly where the model's
        prior ("mil" = million) is wrong for this market, so the code owns the
        meaning and overrides the model's number. A plain "250 000" is left to
        the model, which reads it reliably.
        """
        normalized = self._normalize(text)
        for pattern, multiplier in (
            (SHORTHAND_MILLION_PATTERN, 1_000_000),
            (SHORTHAND_THOUSAND_PATTERN, 1_000),
        ):
            match = pattern.search(normalized)
            if match:
                value = _parse_amount(match.group("amount")) * multiplier
                if value >= MIN_PLAUSIBLE_RENT_XAF:
                    return value
        return None

    def to_intent_result(self, match: DeterministicMatch) -> IntentResult:
        return IntentResult(
            intent=match.intent,
            confidence=match.confidence,
            entities=dict(match.entities),
        )

    def _extract_entities(self, normalized: str) -> dict[str, object]:
        entities: dict[str, object] = {}
        raw_amount, multiplier = self._find_amount(normalized)
        if raw_amount is not None:
            value = _parse_amount(raw_amount) * multiplier
            if value >= MIN_PLAUSIBLE_RENT_XAF:
                entities["price"] = value
        bedrooms = BEDROOM_PATTERN.search(normalized)
        if bedrooms:
            entities["bedrooms"] = int(bedrooms.group("count"))
        bathrooms = BATHROOM_PATTERN.search(normalized)
        if bathrooms:
            entities["bathrooms"] = int(bathrooms.group("count"))
        surface = SURFACE_PATTERN.search(normalized)
        if surface:
            entities["surface_area"] = int(surface.group("area"))
        if NON_MODERN_PATTERN.search(normalized):
            entities["standing"] = "NON_MODERN"
        elif MODERN_PATTERN.search(normalized):
            entities["standing"] = "MODERN"
        location = LOCATION_HINT_PATTERN.search(normalized)
        if location:
            entities["location_hint"] = location.group(0).title()
        return entities

    @staticmethod
    def _find_amount(normalized: str) -> tuple[str | None, int]:
        """The first amount in the message, with its locale multiplier.

        Ordered most-specific first: an explicit "fcfa" beats a shorthand, and a
        million ("million"/"mio") beats a thousand ("mil"/"k") so "50 million is
        not read as 50 000.
        """
        for pattern, multiplier in (
            (AMOUNT_PATTERN, 1),
            (SHORTHAND_MILLION_PATTERN, 1_000_000),
            (SHORTHAND_THOUSAND_PATTERN, 1_000),
        ):
            match = pattern.search(normalized)
            if match:
                return match.group("amount"), multiplier
        for pattern in (GROUPED_AMOUNT_PATTERN, PLAIN_AMOUNT_PATTERN):
            match = pattern.search(normalized)
            if match:
                return match.group(1), 1
        return None, 1

    @staticmethod
    def _first_match(patterns: dict[str, re.Pattern[str]], normalized: str) -> str | None:
        for label, pattern in patterns.items():
            if pattern.search(normalized):
                return label
        return None

    @staticmethod
    def _normalize(text: str) -> str:
        folded = (
            text.strip()
            .casefold()
            .replace("\u202f", " ")
            .replace("\u2019", "'")
        )
        return re.sub(r"\s+", " ", folded)


def _parse_amount(raw: str) -> int:
    digits = re.sub(r"[^\d]", "", raw)
    return int(digits) if digits else 0

