             "oui",
             "non",
             "merci",
         ]
         classifier = DeterministicClassifier()
         emitted = {
             match.intent
             for text in samples
             if (match := classifier.classify(text)) is not None
         }
 
         assert emitted, "the samples must produce at least one intent"
