class TestChargesBreakdown:
    def test_the_eau_electricite_split_is_bound_together(self) -> None:
        classifier = DeterministicClassifier()
        match = classifier.pending_answer("eau 5 000, electricite 10 000", "ask.charges")

        assert match is not None
        assert match.intent == "COLLECT_CHARGES"
        assert match.entities == {
            "water_charges": 5_000,
            "electricity_charges": 10_000,
            "charges": 15_000,
            "charging_policy": "EXTRA",
        }

    def test_the_accented_split_is_understood(self) -> None:
        classifier = DeterministicClassifier()
        match = classifier.pending_answer("eau : 3000, électricité : 12000", "ask.charges")

        assert match is not None
        assert match.entities["charges"] == 15_000

    def test_a_split_totalling_below_the_plausible_floor_is_not_bound(self) -> None:
        classifier = DeterministicClassifier()
        assert (
            classifier.pending_answer("eau 2000, electricite 3000", "ask.charges")
            is None
        )

