    @staticmethod
    def _merge_amenity_detection(entities: dict[str, Any], text: str) -> None:
        """Overlay deterministic amenity signals from the message's own wording.

        Confirmed signals fill the ``amenities`` entity the extractor turns into
        listing facts; probable ones go to ``amenities_hints``, which the
        Property never applies. A model may propose anything, but what the
        landlord *spelled* in the message always wins for these five axes.
        """
        detected = market.infer_amenities(text)
        if not detected:
            return
        confirmed = [
            (field, inference)
            for field, inference in detected.items()
            if inference.level is market.Deduction.CONFIRMED
        ]
        probable = [
            (field, inference)
            for field, inference in detected.items()
            if inference.level is market.Deduction.PROBABLE
        ]
        if confirmed:
            container = entities.setdefault("amenities", {})
            if isinstance(container, dict):
                for field, inference in confirmed:
                    container[field] = inference.value
        if probable:
            container = entities.setdefault("amenities_hints", {})
            if isinstance(container, dict):
                for field, inference in probable:
                    container[field] = inference.value

